CREATE OR REPLACE VIEW pos_demo.v_receipt_summary AS SELECT s.receipt_ref,s.terminal_ref,s.occurred_at,s.currency,s.status,COUNT(l.sale_line_id) AS line_count,COALESCE(SUM(l.quantity),0) AS unit_count,COALESCE(SUM(l.line_total),0) AS receipt_total FROM pos_demo.sales s LEFT JOIN pos_demo.sale_lines l USING(sale_id) GROUP BY s.sale_id;
CREATE OR REPLACE VIEW pos_demo.v_stock_on_hand AS SELECT p.sku,p.label,p.unit_price,p.currency,p.active,COALESCE(SUM(e.quantity_delta),0)::BIGINT AS quantity_on_hand FROM pos_demo.products p LEFT JOIN pos_demo.stock_events e USING(product_id) GROUP BY p.product_id;
CREATE OR REPLACE VIEW pos_demo.v_daily_sales AS SELECT (s.occurred_at AT TIME ZONE 'UTC')::date AS sales_date,s.currency,COUNT(*) AS receipts,SUM(r.receipt_total) AS gross_value FROM pos_demo.v_receipt_summary r JOIN pos_demo.sales s USING(receipt_ref) WHERE s.status<>'voided' GROUP BY (s.occurred_at AT TIME ZONE 'UTC')::date,s.currency;